SELECT CASE WHEN to_regclass('public.mv_headcount_daily') IS NOT NULL AND to_regclass('public.mv_turnover_rate') IS NOT NULL AND to_regclass('public.mv_ferias_balance') IS NOT NULL AND to_regclass('public.mv_afastamento_summary') IS NOT NULL AND EXISTS (SELECT 1 FROM pg_catalog.pg_proc p JOIN pg_catalog.pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname = 'public' AND p.proname = 'refresh_dashboard_views') THEN 'ok' ELSE 'FALHOU: MV de dashboard ausente' END;
